            { "outcome", outcome },
            { "outcomeId", outcomeId },
            { "label", outcomeTitle },
            { "market", marketSymbol },
            { "contracts", shares },
            { "side", "long" },
            { "notional", value },
            { "markPrice", this.safeNumber(position, "price") },
            { "unrealizedPnl", profit },
            { "percentage", this.parseNumber(percentage) },
