        return await this.CreateOrderbookOrder(outcome,type,side,ccxt.BaseExchange.ToDoubleArgRequired(amount),ccxt.BaseExchange.ToDoubleArg(price), parameters);
    }

    /**
     * @ignore
     * @method
     * @name myriad#createAmmOrder
     * @description buys or sells outcome shares by submitting the quote's calldata as an on-chain AMM transaction. Requires a privateKey with gas + collateral on the market's network
     * @param {string} outcome unified outcome or outcome id
     * @param {string} [type] not used by the AMM path
     * @param {string} side 'buy' or 'sell'
     * @param {float} amount for buys this is collateral value to spend (when costDenominated=true); for sells this is shares to sell
     * @param {float} [price] not used by the AMM path
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {object} [params.quote] a pre-fetched fetchTradeQuote result to reuse instead of requesting a new quote, call fetchTradeQuote to retrieve this data
     * @param {string} [params.transactionHash] a pre-broadcast transaction hash; when provided the method skips transaction submission and only parses the order result, capture this value from sendEvmTransaction
     * @param {boolean} [params.skipAllowance] optional override to skip the ERC20 allowance check/approval before a buy; implied true when params.transactionHash is provided
     * @param {boolean} [params.skipWaitForReceipt] optional override to skip the post-send receipt wait; implied true when params.transactionHash is provided
     * @returns {object} a [prediction order structure](https://docs.ccxt.com/#/?id=prediction-order-structure)
     */
    public async virtual Task<ccxt.PredictionOrder> CreateAmmOrder(string outcome, string type, string side, double amount, double? price = null, object parameters = null)
    {
        // the AMM buy endpoint is priced in COLLATERAL, not shares — so a bare createOrder market buy
        // would silently size `amount` as dollars (inconsistent with every other venue and the wiki).
        // route dollar-sizing through createMarketBuyOrderWithCost (which sets costDenominated); a
        // plain createOrder buy on the AMM is rejected so it can't misinterpret shares as collateral
        parameters ??= new Dictionary<string, object>();
        string? sideLower = ((side != null)) ? side.ToLower() : null;
        bool? isCostDenominated = this.safeBool(parameters, "costDenominated", false);
        if ((sideLower == "buy") && ((isCostDenominated != true)))
        {
            throw new NotSupported ((this.id + " createOrder() market buy on the AMM sizes by collateral, not shares — use createMarketBuyOrderWithCost(outcome, collateral) for a dollar buy, or the default order book (omit enableAmm) for a share-denominated order")) ;
        }
        if ((this.privateKey == null))
        {
            throw new ArgumentsRequired ((this.id + " createOrder() requires a privateKey to sign the on-chain transaction")) ;
        }
        await this.loadOutcome(outcome);
        IDictionary<string, object> outcomeObj = this.outcome(outcome);
        IDictionary<string, object> info = this.safeDict(outcomeObj, "info", new Dictionary<string, object>() {});
        string? networkId = this.safeString(info, "networkId");
        IDictionary<string, object> chains = this.safeDict(this.options, "chains", new Dictionary<string, object>() {});
        IDictionary<string, object> chainConfig = this.safeDict(chains, networkId);
        if ((chainConfig == null))
        {
            throw new NotSupported (((this.id + " createOrder() has no on-chain config for network ") + networkId)) ;
        }
        string? rpcUrl = this.safeString2(parameters, "rpcUrl", "rpc", this.safeString(chainConfig, "rpcUrl"));
        string? predictionMarket = this.safeString(chainConfig, "predictionMarket");
        string? tokenAddress = this.safeString2(parameters, "token", "tokenAddress", this.safeString(info, "tokenAddress"));
        string? gasLimit = this.safeString(parameters, "gasLimit", "0xaae60");
        string? sideStr = sideLower;
        object quoteParams = this.omit(parameters, new List<object>() {"rpcUrl", "rpc", "token", "tokenAddress", "gasLimit", "costDenominated", "quote", "transactionHash", "txHash", "skipAllowance", "skipWaitForReceipt"});
        object quote = this.safeDict(parameters, "quote");
        if ((quote == null))
        {
            quote = ccxt.BaseExchange.FromDict(await this.FetchTradeQuote(outcome, sideStr,ccxt.BaseExchange.ToDoubleArgRequired(amount), quoteParams));
        }
        string? calldata = this.safeString(this.safeDict(quote, "info", new Dictionary<string, object>() {}), "calldata");
        if ((calldata == null))
        {
            throw new BadRequest ((this.id + " createAmmOrder is missing calldata from fetchTradeQuote")) ;
        }
        string fromAddress = this.ethGetAddressFromPrivateKey(this.privateKey);
        string? txHashParam = this.safeString2(parameters, "transactionHash", "txHash");
        bool hasPreBroadcastTxHash = ((txHashParam != null));
        bool? skipAllowance = this.safeBool(parameters, "skipAllowance", hasPreBroadcastTxHash);
        if ((sideStr == "buy") && ((tokenAddress != null)) && ((skipAllowance != true)))
        {
            await this.ensureErc20Allowance(rpcUrl, networkId, tokenAddress, fromAddress, predictionMarket);
        }
        bool? skipWaitForReceipt = this.safeBool(parameters, "skipWaitForReceipt", hasPreBroadcastTxHash);
        object txHash = txHashParam;
        if ((txHash == null))
        {
            txHash = await this.sendEvmTransaction(rpcUrl, this.parseToInt(networkId), fromAddress, predictionMarket, "0x0", calldata, gasLimit);
        }
        if ((skipWaitForReceipt != true))
        {
            await this.waitForTransactionReceipt(rpcUrl, txHash);
        }
        return ccxt.BaseExchange.ToPredictionOrder(this.parseTradeTx(txHash, quote, ((object)outcomeObj), sideStr));
    }

    /**
     * @method
     * @name myriad#createMarketBuyOrderWithCost
     * @description buys an outcome by spending a fixed collateral amount on the AMM (dollar-sizing)
     * @see createAmmOrder supports params.quote from fetchTradeQuote(outcome, 'buy', amount)
     * @param {string} outcome unified outcome handle
     * @param {number} cost collateral amount to spend
     * @param {object} [params] extra parameters passed through to createAmmOrder
     * @returns {object} a [prediction order structure](https://docs.ccxt.com/#/?id=prediction-order-structure)
     */
    public async override Task<ccxt.PredictionOrder> CreateMarketBuyOrderWithCost(string outcome, double cost, object parameters = null)
    {
        // myriad's AMM prices buys in COLLATERAL, so `cost` maps directly onto the AMM value input.
        // mark the order cost-denominated so createAmmOrder spends exactly `cost` (not `cost` shares)
        parameters ??= new Dictionary<string, object>();
        Dictionary<string, object> request = this.extend(parameters, new Dictionary<string, object>() {
            { "enableAmm", true },
            { "costDenominated", true },
        });
        return await this.CreateOrder(outcome, "market", "buy",ccxt.BaseExchange.ToDoubleArgRequired(cost),ccxt.BaseExchange.ToDoubleArg(null), request);
    }

    /**
     * @ignore
     * @method
     * @name myriad#signOrderbookTypedData
     * @description EIP-712 signs an order-book typed-data message with the wallet private key (returns a 65-byte 0x signature)
     * @returns {string} the hex signature
     */
    public virtual string signOrderbookTypedData(object types, object message, object networkId)
    {
        IDictionary<string, object> chains = this.safeDict(this.options, "chains", new Dictionary<string, object>() {});
        IDictionary<string, object> chainConfig = this.safeDict(chains, networkId, new Dictionary<string, object>() {});
        string? exchangeAddress = this.safeString(chainConfig, "obExchangeAddress");
        if ((exchangeAddress == null))
        {
            throw new NotSupported ((string)((this.id + " order book trading is not configured for network ") + (networkId))) ;
        }
        string? domainName = this.safeString(this.options, "obDomainName", "MyriadCTFExchange");
        string? domainVersion = this.safeString(this.options, "obDomainVersion", "1");
        Dictionary<string, object> domain = new Dictionary<string, object>() {
            { "name", domainName },
            { "version", domainVersion },
            { "chainId", this.parseToInt(networkId) },
            { "verifyingContract", exchangeAddress },
        };
        byte[] encoded = this.ethEncodeStructuredData(domain, types, message);
        string digest = ((string)this.hash(encoded, keccak, "hex"));
        Dictionary<string, object> signature = ecdsa(digest, this.remove0xPrefix(this.privateKey), secp256k1, null);
        string? rRaw = ((string)(signature != null && ((IDictionary<string, object>)signature).ContainsKey("r") ? ((IDictionary<string, object>)signature)["r"] : null));
        string? sRaw = ((string)(signature != null && ((IDictionary<string, object>)signature).ContainsKey("s") ? ((IDictionary<string, object>)signature)["s"] : null));
        object r = (rRaw as String).PadLeft(Convert.ToInt32(64), Convert.ToChar("0"));
        object s = (sRaw as String).PadLeft(Convert.ToInt32(64), Convert.ToChar("0"));
        object v = this.sum(27, (signature != null && ((IDictionary<string, object>)signature).ContainsKey("v") ? ((IDictionary<string, object>)signature)["v"] : null));
        string sigHex = ((("0x" + (r)) + (s)) + this.intToBase16(v));
        return sigHex.ToLower();
    }

