            { "lastTradeTimestamp", timestamp },
            { "lastUpdateTimestamp", null },
            { "status", "closed" },
            { "outcome", outcome },
            { "outcomeId", composite },
            { "label", label },
            { "market", marketSymbol },
            { "type", "market" },
            { "timeInForce", "IOC" },
            { "postOnly", false },
            { "side", this.safeStringLower(trade, "action") },
            { "price", this.parseNumber(priceStr) },
            { "triggerPrice", null },
            { "amount", this.parseNumber(amountStr) },
            { "filled", this.parseNumber(amountStr) },
            { "remaining", 0 },
            { "cost", this.parseNumber(costStr) },
            { "average", this.parseNumber(priceStr) },
            { "fee", null },
            { "reduceOnly", null },
            { "trades", new List<object>() {} },
            { "event", null },
        }, market);
    }

    /**
     * @ignore
     * @method
     * @name myriad#fetchAmmOrders
     * @description fetches executed AMM trades for a wallet from the user events feed and exposes them as closed prediction orders
     * @param {string} [outcome] unified outcome to filter by
     * @param {int} [since] timestamp in ms of the earliest order
     * @param {int} [limit] the maximum number of orders to return
     * @param {object} [params] extra exchange-specific parameters
     * @returns {object[]} a list of closed [prediction order structures](https://docs.ccxt.com/#/?id=prediction-order-structure)
     */
    public async virtual Task<List<ccxt.PredictionOrder>> FetchAmmOrders(string outcome = null, Int64? since = null, Int64? limit = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        string? requestedStatus = this.safeStringLower(parameters, "status");
        if ((requestedStatus == "open") || (requestedStatus == "cancelled") || (requestedStatus == "canceled") || (requestedStatus == "expired"))
        {
            return ccxt.BaseExchange.ToPredictionOrderList(new List<object>() {});
        }
        string? trader = this.safeString2(parameters, "trader", "address");
        if ((trader == null))
        {
            trader = this.walletAddressOrUndefined();
        }
        if ((trader == null))
        {
            throw new ArgumentsRequired ((this.id + " fetchOrders() for AMM history requires a trader address or wallet/privateKey")) ;
        }
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "address", trader },
        };
        IDictionary<string, object> outcomeObj = null;
        string? outcomeSymbol = null;
        string? rowOutcomeId = null;
        if ((outcome != null))
        {
            outcomeObj = await this.loadOutcome(outcome);
            outcomeSymbol = this.safeString(outcomeObj, "outcome", outcome);
            IDictionary<string, object> info = this.safeDict(outcomeObj, "info", new Dictionary<string, object>() {});
            request["market_id"] = this.safeString(info, "marketId");
            request["network_id"] = this.safeString(info, "networkId");
            rowOutcomeId = this.safeString(info, "outcomeId");
        }
        if ((since != null))
        {
            request["since"] = this.parseToInt((since / 1000));
        }
        if ((limit != null))
        {
            request["limit"] = limit;
        }
        parameters = this.omit(parameters, new List<object>() {"trader", "address", "status"});
        Dictionary<string, object> response = await this.myriadPublicGetUsersAddressEvents(this.extend(request, parameters));
        //
        //     {
        //         "data": [
        //             {
        //                 "user": "0xd282B1436BC99A86eC24A164f7BEeed42CFE8511",
        //                 "action": "sell",
        //                 "marketTitle": "Will Base TGE in 2026?",
        //                 "marketSlug": "will-base-tge-in-2026",
        //                 "marketId": 170145,
        //                 "networkId": 56,
        //                 "outcomeTitle": "Yes",
        //                 "outcomeId": 0,
        //                 "imageUrl": "https://cdn.polkamarkets.com/Qmacfs1qiiUW5cnMRUyzji393Vn2DcvNdydGukf1Xk82b6",
        //                 "shares": 8.22739948,
        //                 "value": 0.9789,
        //                 "timestamp": 1784708801,
        //                 "blockNumber": 111442601,
        //                 "token": "0x8d0D000Ee44948FC98c9B98A4FA4921476f08B0d",
        //                 "txId": "0x93842cbb56b852436f53f7bd5d03580a550c0ac08d49fa80cafaed316d7590d7"
        //             },
        //         ],
        //         "pagination": {
        //             "page": 1,
        //             "limit": 20,
        //             "total": 2,
        //             "totalPages": 1,
        //             "hasNext": false,
        //             "hasPrev": false
        //         }
        //     }
        //
        List<object> rows = this.safeList(response, "data", new List<object>() {});
        List<object> result = new List<object>() {};
        int rowsLength = rows.Count;
        for (int i = 0; i < rowsLength; i++)
        {
            object row = getValue(rows, i);
            string? action = this.safeStringLower(row, "action");
            if ((action != "buy") && (action != "sell"))
            {
                continue;
            }
            string? currentOutcomeId = this.safeString(row, "outcomeId");
            if (((rowOutcomeId != null)) && ((currentOutcomeId != rowOutcomeId)))
            {
                continue;
            }
            result.Add(this.parseAmmEventToOrder(row, outcomeObj));
        }
        List<object> sorted = this.sortBy(result, "timestamp", true);
        return ccxt.BaseExchange.ToPredictionOrderList(this.filterByOutcomeSinceLimit(sorted, outcomeSymbol, since, limit));
    }

    /**
     * @method
     * @name myriad#cancelOrder
     * @description cancels an open order book order by its hash (re-signs the original order to prove ownership; gasless)
     * @see https://docs.myriad.markets/builders/myriad-order-book/order-book-api#37dc9e49da8281b58c5adb2f5998eec8
     * @param {string} id the order hash returned by createOrder
     * @param {string} [outcome] unified outcome the order belongs to
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {object} [params.orderResponse] a pre-fetched fetchOrder-style response for the target order; avoids the internal order lookup when already available, call fetchOrder to retrieve this data
     * @param {object} [params.rawOrder] the raw order payload to sign as an alternative to params.orderResponse, call fetchOrder to retrieve this data
     * @param {string} [params.networkId] the order-book network id, required when using params.rawOrder without an embedded network id
     * @returns {object} a [prediction order structure](https://docs.ccxt.com/#/?id=prediction-order-structure)
     */
    public async override Task<ccxt.PredictionOrder> CancelOrder(string id, string outcome = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        if ((this.privateKey == null))
        {
            throw new ArgumentsRequired ((this.id + " cancelOrder() requires a privateKey to sign the cancellation")) ;
        }
        object fetched = this.getOrderResponseFromParams(id, parameters);
        string? networkIdParam = this.safeString2(parameters, "networkId", "network_id");
        parameters = this.omit(parameters, new List<object>() {"orderResponse", "orderResponses", "rawOrder", "networkId", "network_id"});
        if ((fetched == null))
        {
            fetched = await this.myriadPublicGetOrdersHash(this.extend(new Dictionary<string, object>() {
                { "hash", id },
            }, parameters));
        }
        IDictionary<string, object> fetchedInfo = this.safeDict(fetched, "info", new Dictionary<string, object>() {});
        IDictionary<string, object> rawOrder = this.safeDict(fetched, "order", new Dictionary<string, object>() {});
        List<object> rawOrderKeys = new List<object>(((IDictionary<string,object>)rawOrder).Keys);
        int rawOrderKeysLength = rawOrderKeys.Count;
        if ((rawOrderKeysLength == 0))
        {
            rawOrder = this.safeDict(fetchedInfo, "order", new Dictionary<string, object>() {});
        }
        string? networkId = this.safeStringN(fetched, new List<object>() {"networkId", "network_id"});
        if ((networkId == null))
        {
            networkId = this.safeStringN(fetchedInfo, new List<object>() {"networkId", "network_id"});
        }
        if ((networkId == null))
        {
            networkId = networkIdParam;
        }
        if ((networkId == null))
        {
            networkId = this.safeString(this.options, "defaultNetworkId", "56");
        }
        Dictionary<string, object> message = this.clobOrderMessage(rawOrder);
        string signature = this.signClobOrder(message, networkId);
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "hash", id },
            { "order", message },
            { "signature", signature },
            { "network_id", this.parseToInt(networkId) },
        };
        Dictionary<string, object> response = await this.myriadPublicDeleteOrdersHash(this.extend(request, parameters));
        //
        //     {
        //         "orderHash": "0x758a1763c59bbe61c314f3c0c9b5bae0ad942120500eb39e3e8349bbe13990e0",
        //         "status": "cancelled"
        //     }
        //
        string? status = this.safeString(response, "status", "canceled");
        Dictionary<string, object> wrapper = this.extend(fetched, new Dictionary<string, object>() {
            { "status", status },
            { "networkId", networkId },
        });
        IDictionary<string, object> market = null;
        if ((outcome != null))
        {
            market = await this.loadOutcome(outcome);
        }
        return ccxt.BaseExchange.ToPredictionOrder(this.parsePredictionOrder(wrapper, ((object)market)));
    }

    /**
     * @method
     * @name myriad#cancelAllOrders
     * @description cancels all open order book orders for the wallet, optionally scoped to one market (gasless)
     * @see https://docs.myriad.markets/builders/myriad-order-book/order-book-api#37dc9e49da8281e7a14cd34e6a716761
     * @param {string} [outcome] unified outcome; when omitted cancels across all markets
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object[]} a list with one [prediction order structure](https://docs.ccxt.com/#/?id=prediction-order-structure) whose `info` carries the cancelled count
     */
    public async virtual Task<List<ccxt.PredictionOrder>> CancelAllOrders(string outcome = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        if ((this.privateKey == null))
        {
            throw new ArgumentsRequired ((this.id + " cancelAllOrders() requires a privateKey to sign the cancellation")) ;
        }
        string trader = this.ethGetAddressFromPrivateKey(this.privateKey);
        string? marketId = this.safeString(parameters, "market_id", "0");
        string? networkId = this.safeString(parameters, "network_id", this.safeString(this.options, "defaultNetworkId", "56"));
        if ((outcome != null))
        {
            IDictionary<string, object> outcomeObj = await this.loadOutcome(outcome);
            IDictionary<string, object> info = this.safeDict(outcomeObj, "info", new Dictionary<string, object>() {});
            marketId = this.safeString(info, "marketId", marketId);
            networkId = this.safeString(info, "networkId", networkId);
        }
        // timestamp defaults to now (unix seconds) but can be pinned via params for idempotent retries
        string? timestamp = this.safeString(parameters, "timestamp", this.numberToString(this.seconds()));
        Dictionary<string, object> message = new Dictionary<string, object>() {
            { "trader", trader },
            { "marketId", marketId },
            { "timestamp", timestamp },
        };
        string signature = this.signCancelAll(message, networkId);
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "trader", trader },
            { "market_id", this.parseToInt(marketId) },
            { "timestamp", timestamp },
            { "signature", signature },
            { "network_id", this.parseToInt(networkId) },
        };
        Dictionary<string, object> response = await this.myriadPublicPostOrdersCancelAll(request);
        //
        //     {
        //         "cancelled_count": 2,
        //         "market_ids_affected": [ "2cfe87e8-12df-4671-b9a9-0758898fd54b" ]
        //     }
        //
        // the endpoint returns a count, not the orders: hand back one canceled order
        // structure carrying the raw response, like limitless does
        return ccxt.BaseExchange.ToPredictionOrderList(new List<object> {this.safePredictionOrder(new Dictionary<string, object>() {     { "info", response },     { "status", "canceled" }, })});
    }

    /**
     * @method
     * @name myriad#cancelOrders
     * @description cancels multiple open order book orders by hash in one request (gasless)
     * @see https://docs.myriad.markets/builders/myriad-order-book/order-book-api#37dc9e49da828177961fd94a6055966f
     * @param {string[]} ids the order hashes to cancel
     * @param {string} [outcome] not used by myriad cancelOrders
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {object} [params.orderResponses] pre-fetched fetchOrder-style responses keyed by order hash, or an array of such responses; avoids the internal per-order lookups when already available, call fetchOrder for each id to retrieve this data
     * @param {string} [params.networkId] the order-book network id fallback for any supplied raw order data
     * @returns {object[]} a list of [prediction order structures](https://docs.ccxt.com/#/?id=prediction-order-structure)
     */
    public async override Task<List<ccxt.PredictionOrder>> CancelOrders(object ids, string outcome = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        if ((this.privateKey == null))
        {
            throw new ArgumentsRequired ((this.id + " cancelOrders() requires a privateKey to sign the cancellations")) ;
        }
        object paramsForLookup = parameters;
        string? networkIdParam = this.safeString2(parameters, "networkId", "network_id");
        parameters = this.omit(parameters, new List<object>() {"orderResponse", "orderResponses", "rawOrder", "networkId", "network_id"});
        int idsLength = getArrayLength(ids);
        List<object> signedOrders = new List<object>() {};
        List<object> wrappers = new List<object>() {};
        string? networkId = this.safeString(this.options, "defaultNetworkId", "56");
        for (int i = 0; i < idsLength; i++)
        {
            object id = getValue(ids, i);
            object fetched = this.getOrderResponseFromParams(id, paramsForLookup);
            if ((fetched == null))
            {
                fetched = await this.myriadPublicGetOrdersHash(new Dictionary<string, object>() {
                    { "hash", id },
                });
            }
            IDictionary<string, object> fetchedInfo = this.safeDict(fetched, "info", new Dictionary<string, object>() {});
            IDictionary<string, object> rawOrder = this.safeDict(fetched, "order", new Dictionary<string, object>() {});
            List<object> rawOrderKeys = new List<object>(((IDictionary<string,object>)rawOrder).Keys);
            int rawOrderKeysLength = rawOrderKeys.Count;
            if ((rawOrderKeysLength == 0))
            {
                rawOrder = this.safeDict(fetchedInfo, "order", new Dictionary<string, object>() {});
            }
            string? fetchedNetworkId = this.safeStringN(fetched, new List<object>() {"networkId", "network_id"});
            if ((fetchedNetworkId == null))
            {
                fetchedNetworkId = this.safeStringN(fetchedInfo, new List<object>() {"networkId", "network_id"});
            }
            if ((fetchedNetworkId == null))
            {
                fetchedNetworkId = networkIdParam;
            }
            if ((fetchedNetworkId != null))
            {
                networkId = fetchedNetworkId;
            }
            Dictionary<string, object> message = this.clobOrderMessage(rawOrder);
            string signature = this.signClobOrder(message, networkId);
            signedOrders.Add(new Dictionary<string, object>() {
                { "order", message },
                { "signature", signature },
            });
            wrappers.Add(this.extend(fetched, new Dictionary<string, object>() {
                { "status", "canceled" },
                { "networkId", networkId },
            }));
        }
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "orders", signedOrders },
            { "network_id", this.parseToInt(networkId) },
        };
        await this.myriadPublicPostOrdersCancelBatch(this.extend(request, parameters));
        //
        //     {
        //         "cancelled": [
        //             "0x5d9d278f049c6e159f3028ec9f174e47fdab5a66665306454e6700a2b310736b",
        //             "0x0ad92bb0ec7571ca806cf630b1b78dbd2492015570342ff23c1fa0ea3fcaacff"
        //         ],
        //         "errors": []
        //     }
        //
        return ccxt.BaseExchange.ToPredictionOrderList(this.parsePredictionOrders(wrappers));
    }

    /**
     * @method
     * @name myriad#fetchOrder
     * @description fetches a single order book order by its hash
     * @see https://docs.myriad.markets/builders/myriad-order-book/order-book-api#37dc9e49da828116b8a0d976baea1df0
