    /**
     * @method
     * @name myriad#fetchOrders
     * @description fetches order book orders for the wallet (or any trader passed via params.trader), or amm closed orders
     * @see https://docs.myriad.markets/builders/myriad-order-book/order-book-api#37dc9e49da828171a003cf996487d008
     * @param {string} [outcome] unified outcome to filter by
     * @param {int} [since] timestamp in ms of the earliest order
     * @param {int} [limit] the maximum number of orders to return
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.trader] wallet address to query (defaults to the configured wallet)
     * @param {string} [params.status] 'open', 'filled', 'cancelled' or 'expired'
     * @returns {object[]} a list of [prediction order structures](https://docs.ccxt.com/#/?id=prediction-order-structure)
     */
    public async override Task<List<ccxt.PredictionOrder>> FetchOrders(string outcome = null, Int64? since = null, Int64? limit = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        Dictionary<string, object> request = new Dictionary<string, object>() {};
        string? trader = this.safeString(parameters, "trader");
        if ((trader == null))
        {
            if ((this.privateKey != null))
            {
                request["trader"] = this.ethGetAddressFromPrivateKey(this.privateKey);
            } else if ((this.walletAddress != null))
            {
                request["trader"] = this.walletAddress;
            }
        }
        string? requestedTradingModel = this.safeStringLower2(parameters, "tradingModel", "trading_model");
        parameters = this.omit(parameters, new List<object>() {"tradingModel", "trading_model"});
        IDictionary<string, object> outcomeObj = null;
        string? outcomeSymbol = null;
        if ((outcome != null))
        {
            outcomeObj = await this.loadOutcome(outcome);
            outcomeSymbol = this.safeString(outcomeObj, "outcome", outcome);
            if ((requestedTradingModel == null))
            {
                IDictionary<string, object> info = this.safeDict(outcomeObj, "info", new Dictionary<string, object>() {});
                requestedTradingModel = this.safeStringLower(info, "tradingModel");
            }
        }
        if (requestedTradingModel == "amm")
        {
            return await this.FetchAmmOrders(outcome,ccxt.BaseExchange.ToInt64Arg(since),ccxt.BaseExchange.ToInt64Arg(limit), parameters);
        }
        Dictionary<string, object> response = await this.myriadPublicGetOrders(this.extend(request, parameters));
        //
        //     {
        //         "data": [
        //             {
        //                 "orderHash": "0x88e5c348bedc7336037bf9a2dc3e074431d386a01a2be07763373c794d28ffc2",
        //                 "clientOrderId": null,
        //                 "order": {
        //                     "trader": "0xd282B1436BC99A86eC24A164f7BEeed42CFE8511",
        //                     "marketId": 827,
        //                     "outcomeId": 0,
        //                     "side": 0,
        //                     "amount": "1000000000000000000",
        //                     "price": "10000000000000000",
        //                     "minFillAmount": "0",
        //                     "nonce": "1784713298605",
        //                     "expiration": "0"
        //                 },
        //                 "status": "open",
        //                 "signatureType": 0,
        //                 "filledAmount": "0",
        //                 "timeInForce": "GTC",
        //                 "createdAt": "2026-07-22T09:41:39.035Z",
        //                 "filledAt": null
        //             }
        //         ],
        //         "pagination": {
        //             "page": 1,
        //             "limit": 5000,
        //             "total": 1,
        //             "totalPages": 1,
        //             "hasNext": false,
        //             "hasPrev": false
        //         }
        //     }
        //
        List<object> data = this.safeList(response, "data", new List<object>() {});
        // the /orders endpoint ignores a market_id filter server-side (it returns nothing even for a
        // valid market), so parse every order — each self-resolves its outcome from the network/market/
        // outcome ids — and filter by the requested outcome client-side
        IList<object> orders = this.parsePredictionOrders(data);
        return ccxt.BaseExchange.ToPredictionOrderList(this.filterByOutcomeSinceLimit(orders, outcomeSymbol, since, limit));
    }

