    /**
     * @method
     * @name myriad#fetchMyTrades
     * @description fetches the wallet's filled order book orders as trades. Note: Myriad's REST exposes the order's
     * limit price, not the per-fill execution price, so the price reflects the order's limit (exact for resting/limit
     * fills, an upper/lower bound for market orders) — use watchTrades for live execution prices
     * @see https://docs.myriad.markets/builders/myriad-order-book/order-book-api#37dc9e49da828171a003cf996487d008
     * @param {string} [outcome] unified outcome to filter by
     * @param {int} [since] timestamp in ms of the earliest trade
     * @param {int} [limit] the maximum number of trades to return
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object[]} a list of [prediction trade structures](https://docs.ccxt.com/#/?id=prediction-trade-structure)
     */
    public async override Task<List<ccxt.PredictionTrade>> FetchMyTrades(string outcome = null, Int64? since = null, Int64? limit = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "status", "filled" },
        };
        List<object> orders = ccxt.BaseExchange.FromPredictionOrderList(await this.FetchOrders(outcome,ccxt.BaseExchange.ToInt64Arg(since),ccxt.BaseExchange.ToInt64Arg(limit), this.extend(request, parameters)));
        List<object> trades = new List<object>() {};
        int ordersLength = (orders?.Count ?? 0);
        for (int i = 0; i < ordersLength; i++)
        {
            IDictionary<string, object> order = ((IDictionary<string, object>)getValue(orders, i));
            trades.Add(this.orderToTrade(order));
        }
        return ccxt.BaseExchange.ToPredictionTradeList(this.filterByValueSinceLimit(trades, "outcome", outcome, since, limit, "timestamp", true));
    }

    public virtual object orderToTrade(object order)
    {
        Int64? timestamp = this.safeInteger(order, "timestamp");
        string? orderType = this.safeString(order, "type");
        // the REST filled-order response carries the order's limit price (= the fill price for limit
        // orders, but only the protective bound for market orders), so omit the price for market orders
        double? price = null;
        if (orderType != "market")
        {
            price = this.safeNumber(order, "price");
        }
        return this.safePredictionTrade(new Dictionary<string, object>() {
            { "id", this.safeString(order, "id") },
            { "order", this.safeString(order, "id") },
            { "info", this.safeDict(order, "info", new Dictionary<string, object>() {}) },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "outcome", this.safeString(order, "outcome") },
            { "outcomeId", this.safeString(order, "outcomeId") },
            { "label", this.safeString(order, "label") },
            { "market", this.safeString(order, "market") },
            { "type", orderType },
            { "side", this.safeString(order, "side") },
            { "takerOrMaker", null },
            { "price", price },
            { "amount", this.safeNumber(order, "filled") },
            { "cost", null },
            { "fee", null },
        });
    }

    /**
     * @method
     * @name myriad#fetchBalance
     * @description fetches the wallet's on-chain collateral balance for the order-book network (USD1 on BNB Chain)
     * @see https://docs.myriad.markets/builders/myriad-order-book/order-book-api
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.network_id] the network id (defaults to options.defaultNetworkId, '56')
     * @param {string} [params.network] alias for params.network_id
     * @param {string} [params.currency] output balance currency code override, e.g. 'USDC' or 'USDT'
     * @param {int} [params.decimals] for USDC and USDT it's 6, default is 18 for USD1
     * @returns {object} a [balance structure](https://docs.ccxt.com/#/?id=balance-structure)
     */
    public async override Task<ccxt.Balances> FetchBalance(object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        string? networkId = this.safeString2(parameters, "network_id", "network", this.safeString(this.options, "defaultNetworkId", "56"));
        IDictionary<string, object> chains = this.safeDict(this.options, "chains", new Dictionary<string, object>() {});
        IDictionary<string, object> chainConfig = this.safeDict(chains, networkId, new Dictionary<string, object>() {});
        string? rpcUrl = this.safeString2(parameters, "rpcUrl", "rpc", this.safeString(chainConfig, "rpcUrl"));
        string? token = this.safeString2(parameters, "token", "tokenAddress", this.safeString(chainConfig, "collateralToken"));
        if ((token == null))
        {
            throw new NotSupported (((this.id + " fetchBalance() has no collateral token configured for network ") + networkId)) ;
        }
        string? currency = this.safeString(parameters, "currency", this.safeString(chainConfig, "collateralCurrency", "USD1"));
        Int64? decimals = this.safeInteger(parameters, "decimals", this.safeInteger(chainConfig, "collateralDecimals", 18));
        string owner = this.walletAddressFromKeys();
        // ERC20 balanceOf(owner) = selector 0x70a08231 + the 32-byte left-padded owner address
        string callData = ("0x70a08231" + this.padHexAddress(owner));
        List<object> callParams = new List<object>() {new Dictionary<string, object>() {
    { "to", token },
    { "data", callData },
}, "latest"};
        object raw = await this.ethRpc(rpcUrl, "eth_call", callParams);
        string? balanceString = this.fromWeiWithDecimals(raw, decimals);
        Dictionary<string, object> result = new Dictionary<string, object>() {
            { "info", new Dictionary<string, object>() {
                { "balanceHex", raw },
                { "token", token },
                { "networkId", networkId },
            } },
        };
        Dictionary<string, object> account = this.account();
        account["free"] = balanceString;
        account["total"] = balanceString;
        result[(string)currency] = account;
        return ccxt.BaseExchange.ToBalances(this.safeBalance(result));
    }

    public virtual string? hexToDecimalString(object hexValue)
    {
        // portable hex -> decimal string (avoids convertToBigInt, which is not uniform across languages)
        string stripped = this.remove0xPrefix(hexValue);
        if (((stripped == null)) || (stripped == ""))
        {
            return null;
        }
        List<object> chars = this.stringToCharsArray(stripped.ToLower());
        int n = (chars?.Count ?? 0);
        string digits = "0123456789abcdef";
        string? result = "0";
        for (int i = 0; i < n; i++)
        {
            int v = digits.IndexOf(((string)getValue(chars, i)), StringComparison.Ordinal);
            if (v > -1)
            {
                string? mul = Precise.stringMul(result, "16");
                string? digit = this.numberToString(v);
                result = Precise.stringAdd(mul, digit);
            }
        }
        return result;
    }

    public virtual string? fromWeiWithDecimals(object hexValue, object decimals)
    {
        string? decimalString = this.hexToDecimalString(hexValue);
        if ((decimalString == null))
        {
            return null;
        }
        string scale = "1";
        if (isEqual(decimals, null))
        {
            throw new ExchangeError ((this.id + " fromWeiWithDecimals() missing decimals")) ;
        }
        for (int i = 0; isLessThan(i, decimals); i++)
        {
            scale = (scale + "0");
        }
        return Precise.stringDiv(decimalString, scale);
    }

    public virtual object parseTradeTx(object txHash, object quote, object market, object side)
