     * @param {object} raw the raw myriad market object
     * @param {object} [market] the outcome object the ticker belongs to
     * @returns {object} a [prediction ticker structure](https://docs.ccxt.com/#/?id=prediction-ticker-structure)
     */
    public override Dictionary<string, object> parsePredictionTicker(object raw, object market = null)
    {
        //
        //     {
        //         "id": "756",
        //         "networkId": "2741",
        //         "slug": "will-trump-capture-another-president-before-his-birthday",
        //         "title": "Will Trump capture another president before his birthday?",
        //         "description": "string"
        //         "publishedAt": "2026-01-16T18:05:36.000Z",
        //         "expiresAt": "2026-06-14T04:59:00.000Z",
        //         "resolvesAt": null,
        //         "fees": {
        //             "buy": { "fee": "0.01", "treasury_fee": "0.01", "distributor_fee": "0.01" },
        //             "sell": { "fee": "0", "treasury_fee": "0", "distributor_fee": "0" },
        //             "treasury": "0x5E3EbEc100e2294C0EB2264FC96225dF067AAaa3",
        //             "distributor": "0xE44984C586FeBB31605D23b6316cA11B6f4D86b2"
        //         },
        //         "state": "open",
        //         "voided": false,
        //         "resolvedOutcomeId": "-1",
        //         "topics": [ "Politics" ],
        //         "resolutionSource": "https://www.whitehouse.gov/",
        //         "resolutionTitle": "White House",
        //         "token": {
        //             "name": "Bridged USDC (Stargate)",
        //             "address": "0x84A71ccD554Cc1b02749b35d22F684CC8ec987e1",
        //             "symbol": "USDC.e",
        //             "decimals": "6"
        //         },
        //         "imageUrl": "https://cdn.polkamarkets.com/Qma9FAX15kHewT8vm61vykGA9bqQhNdDLvEbQWSp72i3PQ",
        //         "bannerImageUrl": "https://imagedelivery.net/YN1-rdnufJQJCgu3i1CbVw/255d431f-1bb4-4d90-032b-d1f7032e8000/public",
        //         "ogImageUrl": "https://imagedelivery.net/YN1-rdnufJQJCgu3i1CbVw/cf1af79c-07b9-40f0-283b-ed59865b3c00/public",
        //         "liquidity": "2000",
        //         "liquidityPrice": "0.32532445",
        //         "volume": "10891.236893",
        //         "volume24h": "0.939",
        //         "volumeNotional": "13570.426814",
        //         "volumeNotional24h": "1.028382",
        //         "users": "122",
        //         "shares": "4098.474144",
        //         "featured": false,
        //         "featuredAt": null,
        //         "inPlay": false,
        //         "inPlayStartsAt": null,
        //         "perpetual": false,
        //         "moneyline": false,
        //         "executionMode": "0",
        //         "tradingModel": "amm",
        //         "topHolders": [
        //             "0x8A611AEE71b6448a6F99B6001D1234d020f7d546",
        //             "0x2993249A3D107B759c886a4BD4e02B70d471eA9B",
        //             "0x82a5b3BD2A9216369537583f63fa576a1D57c7E7"
        //         ],
        //         "outcomes": [
        //             {
        //                 "id": "0",
        //                 "title": "Yes",
        //                 "shares": "3742.174971",
        //                 "sharesHeld": "138.741271",
        //                 "price": "0.08693459",
        //                 "closingPrice": null,
        //                 "priceChange24h": "0.00045828",
        //                 "imageUrl": "https://cdn.polkamarkets.com/Qma9FAX15kHewT8vm61vykGA9bqQhNdDLvEbQWSp72i3PQ",
        //                 "holders": "7",
        //                 "tokenId": "1512",
        //                 "price_charts": [Array]
        //             },
        //         ],
        //         "eventId": null,
        //         "outcomeIndex": null,
        //         "negRisk": false,
        //         "externalSources": []
        //     }
        //
        string? outcomeId = ((market != null) && (market != null)) ? this.safeString(getValue(market, "info"), "outcomeId") : null;
        IList<object> outcomes = (IList<object>)(this.safeList(raw, "outcomes", new List<object>() {}));
        double? price = null;
        double? change = null;
        for (int i = 0; i < (outcomes?.Count ?? 0); i++)
        {
            object o = outcomes[i];
            if ((this.safeString(o, "outcomeId", this.safeString(o, "id")) == outcomeId))
            {
                price = this.safeNumber(o, "price");
                change = this.safeNumber(o, "priceChange24h");
                break;
            }
        }
        // priceChange24h is an ABSOLUTE price delta; derive the previous close and the TRUE
        // percentage from it — setting percentage = the absolute change (as before) was wrong
        object previousClose = null;
        object percentage = null;
        if (((price != null)) && ((change != null)))
        {
            previousClose = subtract(price, change);
            if (isEqual(previousClose, null))
            {
                throw new ExchangeError ((this.id + " method() missing previousClose")) ;
            }
            if (!isEqual(previousClose, 0))
            {
                percentage = multiply(divide(change, previousClose), 100);
            }
        }
        return this.safePredictionTicker(new Dictionary<string, object>() {
            { "outcome", this.safeString(market, "outcome") },
            { "outcomeId", this.safeString(market, "id") },
            { "label", this.safeString(market, "label") },
            { "market", this.safeString(market, "market") },
            { "timestamp", null },
            { "datetime", null },
            { "high", null },
            { "low", null },
            { "bid", price },
            { "bidVolume", null },
            { "ask", price },
            { "askVolume", null },
            { "vwap", null },
            { "open", previousClose },
            { "close", price },
            { "last", price },
            { "previousClose", previousClose },
            { "change", change },
            { "percentage", percentage },
            { "average", price },
            { "baseVolume", this.safeNumber(raw, "volumeNotional24h") },
            { "quoteVolume", this.safeNumber(raw, "volume24h") },
            { "info", raw },
        }, market);
    }

    /**
     * @method
     * @name myriad#fetchOrderBook
     * @description fetches the real order book for order-book markets, or synthesizes a one-level book from the AMM price otherwise
     * @see https://docs.myriad.markets/builders/myriad-order-book/order-book-api#37dc9e49da8281bba6aaf24dd61f2bb1
     * @param {string} outcome unified outcome like TRUMP_WIN:YES or an outcome id
     * @param {int} [limit] not used by myriad fetchOrderBook
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a [prediction order book structure](https://docs.ccxt.com/#/?id=prediction-order-book-structure)
     */
    public async override Task<ccxt.PredictionOrderBook> FetchOrderBook(string outcome, Int64? limit = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        IDictionary<string, object> outcomeObj = await this.loadOutcome(outcome);
        string? networkId = this.safeString((outcomeObj != null && ((IDictionary<string, object>)outcomeObj).ContainsKey("info") ? ((IDictionary<string, object>)outcomeObj)["info"] : null), "networkId");
        string? marketId = this.safeString((outcomeObj != null && ((IDictionary<string, object>)outcomeObj).ContainsKey("info") ? ((IDictionary<string, object>)outcomeObj)["info"] : null), "marketId");
        string? outcomeId = this.safeString((outcomeObj != null && ((IDictionary<string, object>)outcomeObj).ContainsKey("info") ? ((IDictionary<string, object>)outcomeObj)["info"] : null), "outcomeId");
        string? tradingModel = this.safeString((outcomeObj != null && ((IDictionary<string, object>)outcomeObj).ContainsKey("info") ? ((IDictionary<string, object>)outcomeObj)["info"] : null), "tradingModel", "amm");
        if (tradingModel == "ob")
        {
            Dictionary<string, object> obRequest = new Dictionary<string, object>() {
                { "id", marketId },
                { "network_id", networkId },
                { "outcome", outcomeId },
            };
            Dictionary<string, object> obResponse = await this.myriadPublicGetMarketsIdOrderbook(this.extend(obRequest, parameters));
            //
            //     {
            //         "bids": [ [ "980000000000000000", "258412594752186597376" ] ],
            //         "asks": [ [ "990000000000000000", "151975683890577539072" ] ]
            //     }
            //
            return ccxt.BaseExchange.ToPredictionOrderBook(this.safePredictionOrderBook(this.parseWeiOrderBook(obResponse, this.safeOutcomeSymbol(outcome, outcomeObj)), outcomeObj));
        }
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "id", marketId },
            { "network_id", networkId },
        };
        Dictionary<string, object> response = await this.myriadPublicGetMarketsId(this.extend(request, parameters));
        //
        //     {
        //         "id": "756",
        //         "networkId": "2741",
        //         "slug": "will-trump-capture-another-president-before-his-birthday",
        //         "title": "Will Trump capture another president before his birthday?",
        //         "shortName": null,
        //         "description": "### **Market Dates:**"
        //         "publishedAt": "2026-01-16T18:05:36.000Z",
        //         "expiresAt": "2026-06-14T04:59:00.000Z",
        //         "resolvesAt": null,
        //         "fees": {
        //             "buy": { "fee": "0.01", "treasury_fee": "0.01", "distributor_fee": "0.01" },
        //             "sell": { "fee": "0", "treasury_fee": "0", "distributor_fee": "0" },
        //             "treasury": "0x5E3EbEc100e2294C0EB2264FC96225dF067AAaa3",
        //             "distributor": "0xE44984C586FeBB31605D23b6316cA11B6f4D86b2"
        //         },
        //         "state": "open",
        //         "voided": false,
        //         "resolvedOutcomeId": "-1",
        //         "topics": [ "Politics" ],
        //         "resolutionSource": "https://www.whitehouse.gov/",
        //         "resolutionTitle": "White House",
        //         "token": {
        //             "name": "Bridged USDC (Stargate)",
        //             "address": "0x84A71ccD554Cc1b02749b35d22F684CC8ec987e1",
        //             "symbol": "USDC.e",
        //             "decimals": "6"
        //         },
        //         "imageUrl": "https://cdn.polkamarkets.com/Qma9FAX15kHewT8vm61vykGA9bqQhNdDLvEbQWSp72i3PQ",
        //         "bannerImageUrl": "https://imagedelivery.net/YN1-rdnufJQJCgu3i1CbVw/255d431f-1bb4-4d90-032b-d1f7032e8000/public",
        //         "ogImageUrl": "https://imagedelivery.net/YN1-rdnufJQJCgu3i1CbVw/d3d60089-3d08-45ac-aa9d-139156e3f900/public",
        //         "liquidity": "2000",
        //         "liquidityPrice": "0.29322839",
        //         "volume": "11396.236893",
        //         "volume24h": "500",
        //         "volumeNotional": "14101.517862",
        //         "volumeNotional24h": "525.779869",
        //         "users": "124",
        //         "shares": "4547.083096",
        //         "featured": false,
        //         "featuredAt": null,
        //         "inPlay": false,
        //         "inPlayStartsAt": null,
        //         "perpetual": false,
        //         "moneyline": false,
        //         "executionMode": "0",
        //         "tradingModel": "amm",
        //         "topHolders": [
        //             "0x8A611AEE71b6448a6F99B6001D1234d020f7d546",
        //             "0x2993249A3D107B759c886a4BD4e02B70d471eA9B"
        //         ],
        //         "outcomes": [
        //             {
        //                 "id": "0",
        //                 "title": "Yes",
        //                 "shares": "4232.024971",
        //                 "sharesHeld": "138.741271",
        //                 "price": "0.06928796",
        //                 "closingPrice": null,
        //                 "priceChange24h": "-0.20109988",
        //                 "imageUrl": "https://cdn.polkamarkets.com/Qma9FAX15kHewT8vm61vykGA9bqQhNdDLvEbQWSp72i3PQ",
        //                 "holders": "7",
        //                 "tokenId": "1512",
        //                 "price_charts": [Array]
        //             }
        //         ],
        //         "eventId": null,
        //         "outcomeIndex": null,
        //         "negRisk": false,
        //         "externalSources": []
        //     }
        //
        IList<object> outcomes = (IList<object>)(this.safeList(response, "outcomes", new List<object>() {}));
        double? price = null;
        for (int i = 0; i < (outcomes?.Count ?? 0); i++)
        {
            object o = outcomes[i];
            if ((this.safeString(o, "outcomeId", this.safeString(o, "id")) == outcomeId))
            {
                price = this.safeNumber(o, "price");
                break;
            }
        }
        // AMM: synthesize a single bid/ask pair around the current implied price, clamped into the valid (0, 1) range
        double? bid = null;
        double? ask = null;
        if ((price != null))
        {
            if (isGreaterThan(price, 0.001))
            {
                bid = this.parseNumber(Precise.stringSub(this.numberToString(price), "0.001"));
            }
            if (isLessThan(price, 0.999))
            {
                ask = this.parseNumber(Precise.stringAdd(this.numberToString(price), "0.001"));
            }
        }
        // the synthetic size must be a parsed float, an int literal breaks the typed go wrapper conversion
        double? synthSize = this.parseNumber("9999");
        List<object> bids = new List<object>() {};
        if ((bid != null))
        {
            bids.Add(new List<object>() {bid, synthSize});
        }
        List<object> asks = new List<object>() {};
        if ((ask != null))
        {
            asks.Add(new List<object>() {ask, synthSize});
        }
        Dictionary<string, object> orderbook = new Dictionary<string, object>() {
            { "outcome", this.safeOutcomeSymbol(outcome, outcomeObj) },
            { "bids", bids },
            { "asks", asks },
            { "timestamp", null },
            { "datetime", null },
            { "nonce", null },
        };
        return ccxt.BaseExchange.ToPredictionOrderBook(this.safePredictionOrderBook(orderbook, outcomeObj));
    }

    /**
     * @ignore
     * @method
     * @name myriad#parseWeiOrderBook
     * @description parses an order book whose price and amount levels are 1e18-scaled integer strings
     * @param {object} response the raw orderbook response with bids and asks arrays
     * @param {string} outcome the unified outcome of the order book
     * @returns {object} a [prediction order book structure](https://docs.ccxt.com/#/?id=prediction-order-book-structure)
     */
    public virtual object parseWeiOrderBook(Dictionary<string, object> response, object outcome)
    {
        IList<object> rawBids = (IList<object>)(this.safeList(response, "bids", new List<object>() {}));
        IList<object> rawAsks = (IList<object>)(this.safeList(response, "asks", new List<object>() {}));
        List<object> bids = new List<object>() {};
        for (int i = 0; i < (rawBids?.Count ?? 0); i++)
        {
            object row = rawBids[i];
            string? rowPrice = Precise.stringDiv(this.safeString(row, 0), "1000000000000000000");
            string? rowAmount = Precise.stringDiv(this.safeString(row, 1), "1000000000000000000");
            bids.Add(new List<object> {this.parseNumber(rowPrice), this.parseNumber(rowAmount)});
        }
        List<object> asks = new List<object>() {};
        for (int i = 0; i < (rawAsks?.Count ?? 0); i++)
        {
            object row = rawAsks[i];
            string? rowPrice = Precise.stringDiv(this.safeString(row, 0), "1000000000000000000");
            string? rowAmount = Precise.stringDiv(this.safeString(row, 1), "1000000000000000000");
            asks.Add(new List<object> {this.parseNumber(rowPrice), this.parseNumber(rowAmount)});
        }
        return new Dictionary<string, object>() {
            { "outcome", outcome },
            { "bids", this.sortBy(bids, 0, true) },
            { "asks", this.sortBy(asks, 0) },
            { "timestamp", null },
            { "datetime", null },
            { "nonce", null },
        };
    }

    /**
     * @method
     * @name myriad#fetchOHLCV
     * @description fetches price history for an outcome from the price_charts bucket embedded in the market response
     * @see https://docs.myriad.markets/builders/myriad-api-reference
     * @param {string} outcome unified outcome like TRUMP_WIN:YES or an outcome id
     * @param {string} timeframe mapped to the closest available chart bucket (24h, 7d or 30d)
     * @param {int} [since] timestamp in ms of the earliest candle to fetch
     * @param {int} [limit] the maximum number of candles to return
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {int[][]} a list of candles ordered as timestamp, open, high, low, close, volume
     */
    public async override Task<List<ccxt.OHLCV>> FetchOHLCV(string outcome, string timeframe = null, Int64? since = null, Int64? limit = null, object parameters = null)
    {
        string timeframeVar = timeframe;
        timeframeVar ??= "1d";
        parameters ??= new Dictionary<string, object>();
        IDictionary<string, object> outcomeObj = await this.loadOutcome(outcome);
        IDictionary<string, object> outcomeInfo = this.safeDict(outcomeObj, "info", new Dictionary<string, object>() {});
        string? networkId = this.safeString((outcomeObj != null && ((IDictionary<string, object>)outcomeObj).ContainsKey("info") ? ((IDictionary<string, object>)outcomeObj)["info"] : null), "networkId");
        string? marketId = this.safeString((outcomeObj != null && ((IDictionary<string, object>)outcomeObj).ContainsKey("info") ? ((IDictionary<string, object>)outcomeObj)["info"] : null), "marketId");
        string? outcomeId = this.safeString(outcomeInfo, "outcomeId", this.safeString(outcomeInfo, "id"));
        string? outcomeTitle = this.safeString(outcomeInfo, "outcomeLabel", this.safeString(outcomeInfo, "label", this.safeString(outcomeInfo, "title")));
        string? bucketKey = this.safeString(this.timeframes, timeframeVar, "30d");
        Dictionary<string, object> response = await this.myriadPublicGetMarketsId(this.extend(new Dictionary<string, object>() {
            { "id", marketId },
            { "network_id", networkId },
        }, parameters));
        //
        //     {
        //         "id": "164",
        //         "networkId": "2741",
        //         "slug": "trump-out-as-president-2027",
        //         "title": "Will Trump cease to be President before 2027?",
        //         "state": "open",
        //         "outcomes": [
        //             {
        //                 "id": "0",
        //                 "outcomeId": "0",
        //                 "title": "YES",
        //                 "label": "YES",
        //                 "price": 0.42,
        //                 "priceChange24h": -0.02
        //             }
        //         ],
        //         "price_charts": {
        //             "24h": {
        //                 "timeframe": "24h",
        //                 "prices": [
        //                     {
        //                         "timestamp": 1705318200,
        //                         "open": 0.40,
        //                         "high": 0.45,
        //                         "low": 0.39,
        //                         "close": 0.42,
        //                         "price": 0.42,
        //                         "value": 0.42
        //                     }
        //                 ]
        //             },
        //             "7d": {...},
        //             "30d": {...}
        //         }
        //     }
        //
        IList<object> outcomes = (IList<object>)(this.safeList(response, "outcomes", new List<object>() {}));
        object selectedOutcome = null;
        for (int i = 0; i < (outcomes?.Count ?? 0); i++)
        {
            object oc = outcomes[i];
            string? currentId = this.safeString(oc, "id", this.safeString(oc, "outcomeId"));
            string? currentTitle = this.safeString(oc, "title", this.safeString(oc, "label"));
            if (((outcomeId != null)) && ((currentId == outcomeId)))
            {
                selectedOutcome = oc;
                break;
            }
            if (((selectedOutcome == null)) && ((outcomeTitle != null)) && ((currentTitle == outcomeTitle)))
            {
                selectedOutcome = oc;
            }
        }
        // price_charts is a list of { timeframeVar, prices } buckets, with a dict variant on some deployments
        object chart = null;
        List<object> chartsList = this.safeList(selectedOutcome, "price_charts");
        if ((chartsList != null))
        {
            for (int i = 0; i < chartsList.Count; i++)
            {
                object chartObj = chartsList[i];
                if ((this.safeString(chartObj, "timeframe") == bucketKey))
                {
                    chart = chartObj;
                    break;
                }
            }
        } else
        {
            IDictionary<string, object> chartsDict = this.safeDict(selectedOutcome, "price_charts", new Dictionary<string, object>() {});
            chart = this.safeValue(chartsDict, bucketKey);
        }
        List<object> pointsList = this.safeList(chart, "prices", this.safeList(chart, "data", ((object)chart)));
        IList<object> points = ((pointsList != null)) ? pointsList : new List<object>() {};
        int pointsLength = (points?.Count ?? 0);
        if ((pointsLength == 0))
        {
            IDictionary<string, object> priceCharts = this.safeDict(response, "price_charts", new Dictionary<string, object>() {});
            object bucket = this.safeValue(priceCharts, bucketKey, new Dictionary<string, object>() {});
            points = (IList<object>)(this.safeList(bucket, outcomeId, this.safeList(bucket, "data", new List<object>() {})));
        }
        List<object> usablePoints = new List<object>() {};
        for (int i = 0; i < (points?.Count ?? 0); i++)
        {
            object point = points[i];
            double? pointOpen = this.safeNumber(point, "open");
            double? pointPrice = this.safeNumber(point, "price", this.safeNumber(point, "value"));
            Int64? pointTs = this.safeInteger(point, "timestamp");
            if ((((pointOpen != null)) || ((pointPrice != null))) && ((pointTs != null)))
            {
                usablePoints.Add(point);
            }
        }
        return ccxt.BaseExchange.ToOHLCVList(this.parseOHLCVs(usablePoints, outcomeObj,timeframeVar, since, limit));
    }

    /**
     * @ignore
     * @method
     * @name myriad#parseOHLCV
     * @description parses a single myriad price chart data point into an ohlcv tuple
     * @param {object} ohlcv the raw price chart data point
     * @param {object} [market] the outcome object the candle belongs to
     * @returns {int[]} a candle ordered as timestamp, open, high, low, close, volume
     */
    public override IList<object> parseOHLCV(object ohlcv, object market = null)
    {
        //
        //     {
        //         "timestamp": 1705318200,
        //         "open": 0.40,
        //         "high": 0.45,
        //         "low": 0.39,
        //         "close": 0.42,
        //         "price": 0.42,
        //         "value": 0.42
        //     }
        //
        double? open = this.safeNumber(ohlcv, "open");
        double? high = this.safeNumber(ohlcv, "high");
        double? low = this.safeNumber(ohlcv, "low");
        double? close = this.safeNumber(ohlcv, "close");
        double? price = this.safeNumber(ohlcv, "price", this.safeNumber(ohlcv, "value")); // fallback single-value tick
        return new List<object> {this.safeTimestamp(ohlcv, "timestamp"), ((open != null)) ? open : price, ((high != null)) ? high : price, ((low != null)) ? low : price, ((close != null)) ? close : price, 0};
    }

    /**
     * @method
     * @name myriad#fetchTickers
     * @description fetches tickers for multiple outcomes, grouping requested outcomes by their parent market to fetch each market only once
     * @see https://docs.myriad.markets/builders/myriad-api-reference
     * @param {string[]} outcomes unified outcomes — required: myriad has no endpoint returning all tickers at once, so an unscoped call is not supported
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a dictionary of [prediction ticker structures](https://docs.ccxt.com/#/?id=prediction-ticker-structure) indexed by outcome
     */
    public async override Task<ccxt.PredictionTickers> FetchTickers(IList<object> outcomes = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        if ((outcomes == null))
        {
            throw new ArgumentsRequired ((this.id + " fetchTickers() requires an outcomes argument — the venue has no all-tickers endpoint; pass the outcome handles to fetch (discover them via fetchEvents ())")) ;
        }
        Dictionary<string, object> result = new Dictionary<string, object>() {};
        // resolve the uncached outcomes first, then group by parent market to fetch each market only once
        await this.loadOutcomes(outcomes);
        Dictionary<string, object> outcomesByMarket = new Dictionary<string, object>() {};
        List<object> marketKeys = new List<object>() {};
        for (int i = 0; i < (outcomes?.Count ?? 0); i++)
        {
            IDictionary<string, object> outcomeObj = this.outcome(getValue(outcomes, i));
            IDictionary<string, object> info = this.safeDict(outcomeObj, "info", new Dictionary<string, object>() {});
            object networkId = this.safeString(info, "networkId");
            string? marketId = this.safeString(info, "marketId");
            object key = add(add(networkId, ":"), marketId);
            if (!(inOp(outcomesByMarket, key)))
            {
                outcomesByMarket[(string)key] = new List<object>() {};
                marketKeys.Add(key);
            }
            // reassign after push, plain mutation through a local is lost in transpiled php (arrays are value types there)
            object grouped = getValue(outcomesByMarket, key);
            ((IList<object>)grouped).Add(outcomeObj);
            outcomesByMarket[(string)key] = grouped;
        }
        List<object> promises = new List<object>() {};
        for (int i = 0; i < (marketKeys?.Count ?? 0); i++)
        {
            object key = marketKeys[i];
            IList<object> grouped = (IList<object>)(getValue(outcomesByMarket, key));
            object firstOutcome = getValue(grouped, 0);
            IDictionary<string, object> info = this.safeDict(firstOutcome, "info", new Dictionary<string, object>() {});
            promises.Add(this.myriadPublicGetMarketsId(this.extend(new Dictionary<string, object>() {
                { "id", this.safeString(info, "marketId") },
                { "network_id", this.safeString(info, "networkId") },
            }, parameters)));
        }
        List<object> responses = await promiseAll(promises);
        for (int i = 0; i < (marketKeys?.Count ?? 0); i++)
        {
            object key = marketKeys[i];
            object response = getValue(responses, i);
            IList<object> grouped = (IList<object>)(getValue(outcomesByMarket, key));
            for (int j = 0; j < (grouped?.Count ?? 0); j++)
            {
                object outcomeObj = grouped[j];
                Dictionary<string, object> ticker = this.parsePredictionTicker(response, outcomeObj);
                string? symbolKey = this.safeString(ticker, "outcome");
                if ((symbolKey != null))
                {
                    result[(string)symbolKey] = ticker;
                }
            }
        }
        return ccxt.BaseExchange.ToPredictionTickers(result);
    }

    /**
     * @method
     * @name myriad#fetchTrades
     * @description fetches recent public trades for a single outcome from the market action feed
     * @see https://docs.myriad.markets/builders/myriad-api-reference
     * @param {string} outcome unified outcome like TRUMP_WIN:YES or an outcome id
     * @param {int} [since] timestamp in ms of the earliest trade to fetch
     * @param {int} [limit] the maximum number of trades to return
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object[]} a list of [prediction trade structures](https://docs.ccxt.com/#/?id=prediction-trade-structure)
     */
    public async override Task<List<ccxt.PredictionTrade>> FetchTrades(string outcome, Int64? since = null, Int64? limit = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        IDictionary<string, object> outcomeObj = await this.loadOutcome(outcome);
        IDictionary<string, object> info = this.safeDict(outcomeObj, "info", new Dictionary<string, object>() {});
        string? networkId = this.safeString(info, "networkId");
        string? marketId = this.safeString(info, "marketId");
        string? outcomeId = this.safeString(info, "outcomeId");
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "id", marketId },
            { "network_id", networkId },
        };
        if ((limit != null))
        {
            request["limit"] = limit;
        }
        Dictionary<string, object> response = await this.myriadPublicGetMarketsIdEvents(this.extend(request, parameters));
        //
        //     {
        //         "data": [
        //             {
        //                 "user": "0xAE7Bfff784EeEe7812D6527B72c77A7Ed773Ed9D",
        //                 "action": "buy",
        //                 "marketTitle": "BNB candles from 10:00 to 10:05 UTC",
        //                 "marketSlug": "bnb-candles-from-10-00-to-10-05-utc",
        //                 "marketId": 218,
        //                 "networkId": 56,
        //                 "outcomeTitle": "More Green",
        //                 "outcomeId": 0,
        //                 "shares": 500,
        //                 "value": 500,
        //                 "timestamp": 1761645928,
        //                 "blockNumber": 66193433,
        //                 "token": "0x55d398326f99059fF775485246999027B3197955",
        //                 "txId": "0x3c81447bd6e5c4c80a6e1425383c0b044ddcb1525d09027c2b371ff84f9b9fa0"
        //             }
        //         ]
        //     }
        //
        bool responseIsArray = ((response is IList<object>) || (response.GetType().IsGenericType && response.GetType().GetGenericTypeDefinition().IsAssignableFrom(typeof(List<>))));
        object rowsList = responseIsArray ? response : this.safeList(response, "data", new List<object>() {});
        object rows = ((rowsList != null)) ? rowsList : new List<object>() {};
        List<object> trades = new List<object>() {};
        for (int i = 0; i < getArrayLength(rows); i++)
        {
            object row = getValue(rows, i);
            string? action = this.safeString(row, "action");
            if ((action != "buy") && (action != "sell"))
            {
                continue;
            }
            string? rowOutcomeId = this.safeString(row, "outcomeId");
            if (((outcomeId != null)) && ((rowOutcomeId != outcomeId)))
            {
                continue;
            }
            trades.Add(row);
        }
        return ccxt.BaseExchange.ToPredictionTradeList(this.parsePredictionTrades(trades, outcomeObj, since, limit));
    }

    /**
     * @ignore
     * @method
     * @name myriad#parsePredictionTrade
     * @description parses a raw market action feed row into a unified trade object
     * @param {object} trade the raw action feed row
     * @param {object} [market] the outcome object the trade belongs to
     * @returns {object} a [prediction trade structure](https://docs.ccxt.com/#/?id=prediction-trade-structure)
     */
    public override Dictionary<string, object> parsePredictionTrade(object trade, object market = null)
    {
        Int64? timestamp = this.safeTimestamp(trade, "timestamp");
        string? amountStr = this.safeString(trade, "shares");
        string? costStr = this.safeString(trade, "value");
        string? priceStr = null;
        if (((amountStr != null)) && ((costStr != null)) && !Precise.stringEq(amountStr, "0"))
        {
            priceStr = Precise.stringDiv(costStr, amountStr);
        }
        return this.safePredictionTrade(new Dictionary<string, object>() {
            { "id", this.safeString(trade, "txId") },
            { "info", trade },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "outcome", this.safeString(market, "outcome") },
            { "outcomeId", this.safeString(market, "id") },
